from typing import Optional

class Solution:
    def deleteNodes(self, head: ListNode, m: int, n: int) -> Optional[ListNode]:
        kept, position = [], 0
        while head:
            if position % (m + n) < m:
                kept.append(head)
            position += 1
            head = head.next
        for i, node in enumerate(kept):
            node.next = kept[i + 1] if i + 1 < len(kept) else None
        return kept[0] if kept else None
